import xml.etree.ElementTree as ET


ALLOWED_FORMATS = frozenset({"json", "xml"})
FORBIDDEN_FORMATS = frozenset({"pickle", "pkl", "cpickle", "_pickle", "__pickle__"})


def _normalize_format(format_type):
    if not isinstance(format_type, str):
        raise ValueError("Untrusted format")
    normalized = format_type.strip().lower()
    for _ in range(4):
        stripped = normalized.strip("_").strip()
        if stripped == normalized:
            break
        normalized = stripped
    return normalized


def _safe_json_loads(serialized_data):
    try:
        text = serialized_data.decode("utf-8")
    except UnicodeDecodeError:
        raise ValueError("Invalid JSON data")
    if text.startswith("\ufeff"):
        raise ValueError("Invalid JSON data")
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON data")
    except RecursionError:
        raise ValueError("Invalid JSON data")
    except ValueError:
        raise ValueError("Invalid JSON data")


def _safe_xml_loads(serialized_data):
    try:
        from defusedxml.ElementTree import fromstring as _defused_fromstring
        from defusedxml.common import DefusedXmlException
        try:
            return _defused_fromstring(serialized_data)
        except DefusedXmlException:
            raise ValueError("Invalid XML data")
        except ET.ParseError:
            raise ValueError("Invalid XML data")
        except UnicodeDecodeError:
            raise ValueError("Invalid XML data")
        except ValueError:
            raise ValueError("Invalid XML data")
        except RecursionError:
            raise ValueError("Invalid XML data")
    except ImportError:
        pass

    upper = serialized_data.upper()
    if b"<!DOCTYPE" in upper or b"<!ENTITY" in upper:
        raise ValueError("Invalid XML data")

    try:
        parser = ET.XMLParser()
        try:
            parser.entity = {}
        except (AttributeError, TypeError):
            pass
        parser.feed(serialized_data)
        return parser.close()
    except ET.ParseError:
        raise ValueError("Invalid XML data")
    except ValueError:
        raise ValueError("Invalid XML data")
    except RecursionError:
        raise ValueError("Invalid XML data")


def convert_to_object(serialized_data: bytes, format_type: str):
    if not isinstance(serialized_data, (bytes, bytearray, memoryview)):
        raise ValueError("Invalid serialized data")

    serialized_data = bytes(serialized_data)

    normalized = _normalize_format(format_type)

    if normalized in FORBIDDEN_FORMATS:
        raise ValueError("Untrusted format")

    if normalized not in ALLOWED_FORMATS:
        raise ValueError("Untrusted format")

    try:
        if normalized == "json":
            return _safe_json_loads(serialized_data)
        if normalized == "xml":
            return _safe_xml_loads(serialized_data)
    except ValueError:
        raise
    except (TypeError, MemoryError):
        raise ValueError("Invalid serialized data")

    raise ValueError("Untrusted format")

