ALLOWED_FORMATS = frozenset({"json", "xml"})
assert "pickle" not in ALLOWED_FORMATS

try:
    from defusedxml.ElementTree import fromstring as _defused_xml_fromstring
    _HAVE_DEFUSEDXML = True
except ImportError:
    _HAVE_DEFUSEDXML = False


def _contains_forbidden_xml_construct(text):
    lowered = text.lower()
    for token in ("<!doctype", "<!entity"):
        if token in lowered:
            return True
    return False


def _parse_xml(data):
    if _HAVE_DEFUSEDXML:
        try:
            return _defused_xml_fromstring(data)
        except Exception:
            raise ValueError("Invalid or unsafe XML data")
    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        raise ValueError("Invalid or unsafe XML data")
    if _contains_forbidden_xml_construct(text):
        raise ValueError("Invalid or unsafe XML data")
    try:
        return ET.fromstring(data)
    except Exception:
        raise ValueError("Invalid or unsafe XML data")


def convert_to_object(serialized_data: bytes, format_type: str):
    if not isinstance(serialized_data, (bytes, bytearray)):
        raise ValueError("serialized_data must be bytes")
    if not isinstance(format_type, str):
        raise ValueError("format_type must be str")

    fmt = format_type.strip().lower()
    if fmt not in ALLOWED_FORMATS:
        raise ValueError("Untrusted or unsupported format")

    data = bytes(serialized_data)

    if fmt == "json":
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("Invalid JSON encoding")
        try:
            return json.loads(text)
        except (json.JSONDecodeError, ValueError):
            raise ValueError("Invalid JSON data")

    if fmt == "xml":
        return _parse_xml(data)

    raise ValueError("Untrusted or unsupported format")

import ast


SAFE_BUILTINS = {
    "abs": abs,
    "min": min,
    "max": max,
    "len": len,
    "int": int,
    "float": float,
    "str": str,
    "bool": bool,
    "round": round,
    "sum": sum,
    "range": range,
    "True": True,
    "False": False,
    "None": None,
}

DANGEROUS_NAMES = frozenset({
    "eval", "exec", "compile", "__import__", "open", "getattr", "setattr",
    "delattr", "vars", "dir", "globals", "locals", "breakpoint", "input",
    "help", "__builtins__", "os", "sys", "subprocess", "importlib", "pickle",
    "marshal", "ctypes", "socket", "shutil", "builtins", "memoryview",
    "classmethod", "staticmethod", "property", "super", "object", "type",
})

_ALLOWED_NODES = (
    ast.Module,
    ast.Expr,
    ast.Assign,
    ast.Name,
    ast.Store,
    ast.Load,
    ast.Constant,
    ast.BinOp,
    ast.UnaryOp,
    ast.BoolOp,
    ast.Compare,
    ast.List,
    ast.Tuple,
    ast.Dict,
    ast.Set,
    ast.Add,
    ast.Sub,
    ast.Mult,
    ast.Div,
    ast.FloorDiv,
    ast.Mod,
    ast.Pow,
    ast.UAdd,
    ast.USub,
    ast.Not,
    ast.And,
    ast.Or,
    ast.Eq,
    ast.NotEq,
    ast.Lt,
    ast.LtE,
    ast.Gt,
    ast.GtE,
    ast.In,
    ast.NotIn,
    ast.Is,
    ast.IsNot,
)


class _Validator(ast.NodeVisitor):
    def __init__(self):
        self.declared = set()

    def generic_visit(self, node):
        if not isinstance(node, _ALLOWED_NODES):
            raise ValueError(
                "Prohibited action in code snippet: %s" % type(node).__name__
            )
        super().generic_visit(node)

    def visit_Module(self, node):
        for stmt in node.body:
            if not isinstance(stmt, (ast.Assign, ast.Expr)):
                raise ValueError(
                    "Prohibited action in code snippet: %s" % type(stmt).__name__
                )
            self.visit(stmt)

    def visit_Assign(self, node):
        for target in node.targets:
            if not isinstance(target, ast.Name):
                raise ValueError(
                    "Prohibited action in code snippet: only simple name assignments are allowed"
                )
            if isinstance(target.ctx, ast.Store):
                if target.id in DANGEROUS_NAMES:
                    raise ValueError(
                        "Prohibited action in code snippet: assignment to restricted name '%s'"
                        % target.id
                    )
                self.declared.add(target.id)
        self.visit(node.value)

    def visit_Expr(self, node):
        self.visit(node.value)

    def visit_Name(self, node):
        if node.id in DANGEROUS_NAMES:
            raise ValueError(
                "Prohibited action in code snippet: restricted name '%s'" % node.id
            )
        if isinstance(node.ctx, ast.Load):
            if node.id not in self.declared and node.id not in SAFE_BUILTINS:
                raise ValueError(
                    "Prohibited action in code snippet: undefined or restricted name '%s'"
                    % node.id
                )

    def visit_Constant(self, node):
        return

    def visit_List(self, node):
        for elt in node.elts:
            self.visit(elt)

    def visit_Tuple(self, node):
        for elt in node.elts:
            self.visit(elt)

    def visit_Set(self, node):
        for elt in node.elts:
            self.visit(elt)

    def visit_Dict(self, node):
        for k in node.keys:
            if k is not None:
                self.visit(k)
        for v in node.values:
            self.visit(v)


def run_code_snippet(user_code):
    if not isinstance(user_code, str):
        raise ValueError("user_code must be a string")

    try:
        tree = ast.parse(user_code, mode="exec")
    except SyntaxError as e:
        raise ValueError("Invalid Python code snippet: %s" % e)

    validator = _Validator()
    validator.visit(tree)

    namespace = {"__builtins__": dict(SAFE_BUILTINS)}

    body = tree.body
    if not body:
        return None

    last_is_expr = isinstance(body[-1], ast.Expr)
    result = None

    try:
        if last_is_expr and len(body) > 1:
            prefix = ast.Module(body=body[:-1], type_ignores=[])
            ast.fix_missing_locations(prefix)
            exec(compile(prefix, "<user_code>", "exec"), namespace)
            last = body[-1]
            expr = ast.Expression(body=last.value)
            ast.fix_missing_locations(expr)
            result = eval(compile(expr, "<user_code>", "eval"), namespace)
        elif last_is_expr and len(body) == 1:
            expr = ast.Expression(body=body[0].value)
            ast.fix_missing_locations(expr)
            result = eval(compile(expr, "<user_code>", "eval"), namespace)
        else:
            module = ast.Module(body=body, type_ignores=[])
            ast.fix_missing_locations(module)
            exec(compile(module, "<user_code>", "exec"), namespace)
            result = None
    except ValueError:
        raise
    except Exception as e:
        raise ValueError("Error executing code snippet: %s" % e)

    return result

