def modify_car_details(car, changes):
    if not isinstance(car, dict):
        raise TypeError("car must be a dict")
    if not isinstance(changes, dict):
        raise TypeError("changes must be a dict")

    local_allowed = frozenset(
        field for field in ALLOWED_FIELDS if isinstance(field, str)
    )

    items = list(changes.items())

    for key, value in items:
        if not isinstance(key, str):
            raise ValueError(
                "Field key must be a string: {!r}".format(key)
            )
        if key not in local_allowed:
            raise ValueError(
                "Field '{}' is not allowed to be modified. Allowed fields: {}".format(
                    key, sorted(local_allowed)
                )
            )
        if key in _STRING_FIELDS:
            if not isinstance(value, str):
                raise ValueError(
                    "Field '{}' must be a string".format(key)
                )
            if len(value) == 0:
                raise ValueError(
                    "Field '{}' must be a non-empty string".format(key)
                )
            if len(value) > _MAX_STRING_LENGTH:
                raise ValueError(
                    "Field '{}' exceeds maximum length of {}".format(
                        key, _MAX_STRING_LENGTH
                    )
                )
        elif key in _NUMBER_FIELDS:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    "Field '{}' must be an int or float".format(key)
                )
            if value < 0:
                raise ValueError(
                    "Field '{}' must be non-negative".format(key)
                )

    updated_car = dict(car)
    for key, value in items:
        updated_car[key] = value
    return updated_car

